      "achados": [
        {
          "proposicao": "Projetos brasileiros de descomissionamento podem exigir planejamento específico para içamentos pesados e apoio marítimo porque há pouca disponibilidade regional de embarcações especializadas, como heavy lift.",
          "trechos": [
            "E3edd6ed0775ad31a:1397:2096"
          ],
          "condicoes": [
            "contexto de projetos de descomissionamento no Brasil, especialmente com particularidades citadas para a Bacia de Campos"
          ],
          "limites": [
            "o trecho caracteriza desafio logístico; não define critério de seleção, capacidade mínima, sequência operacional nem requisito normativo"
          ]
        },
        {
          "proposicao": "A grande variação de lâmina d'água, o uso extensivo de dutos flexíveis e umbilicais e a grande quantidade de poços submarinos compõem um cenário técnico que afeta o planejamento integrado do descomissionamento.",
          "trechos": [
            "E3edd6ed0775ad31a:697:1397",
            "E3edd6ed0775ad31a:1397:2096"
          ],
          "condicoes": [
            "aplicável ao cenário descrito de sistemas submarinos e projetos da PETROBRAS no Brasil"
          ],
          "limites": [
            "o trecho não detalha como essas variáveis alteram distribuição de pesos, resistência estrutural da unidade ou gestão de SIMOPS"
          ]
        },
        {
          "proposicao": "A presença de cenários ambientais sensíveis e de espécies exóticas invasoras amplia a complexidade do planejamento e da avaliação de alternativas de descomissionamento.",
          "trechos": [
            "E3edd6ed0775ad31a:1397:2096",
            "E3edd6ed0775ad31a:2096:2333"
          ],
          "condicoes": [
            "quando o projeto ocorre em áreas com bancos de algas calcárias, corais de águas profundas ou espécies invasoras"
          ],
          "limites": [
            "o trecho não estabelece medida de controle operacional específica para desmontagem offshore da unidade"
          ]
        }
      ]
    },
    {
      "id": "E0a31d2617509e9d2",
